const seedEmployees=[];
    const statusLabels={present:'حاضر',late:'متأخر',absent:'غائب',leave:'إجازة'};
    const viewTitles={overview:'نظرة عامة',employees:'الموظفون',attendance:'الحضور والانصراف',schedules:'مواعيد العمل',payroll:'الرواتب والمكافآت',requests:'طلبات الموظفين',reports:'التقارير',settings:'الإعدادات'};
    const requestStatusLabels={pending:'قيد المراجعة',approved:'مقبول',rejected:'مرفوض'};
    const DATA_BACKUP_FORMAT='dawam-local-backup';const DATA_STORAGE_KEYS=['dawamEmployees','dawamRequests','dawamNotifications','dawamAdminPassword','dawamCompany'];
    let employees=loadEmployees();let requests=loadRequests();let notifications=loadNotifications();let activeView='overview';let attendanceFilter='all';let currentUser=readSession();
    function loadEmployees(){let saved;try{saved=JSON.parse(localStorage.getItem('dawamEmployees'))}catch{}return (saved||seedEmployees).map((e,i)=>({...e,username:e.username||`emp-${String(i+1).padStart(3,'0')}`,accountType:e.accountType||'employee'}))}
    function loadRequests(){try{let saved=JSON.parse(localStorage.getItem('dawamRequests'));return Array.isArray(saved)?saved:[]}catch{return []}}
    function saveRequests(){let previous=loadRequests();localStorage.setItem('dawamRequests',JSON.stringify(requests));let count=document.getElementById('navRequestCount');if(count)count.textContent=arabic(requests.filter(request=>request.status==='pending').length);requests.forEach(request=>{let old=previous.find(item=>item.id===request.id);if(!old)notifyRequestReviewers(request);else if(old.status!==request.status&&(request.status==='approved'||request.status==='rejected'))notify(request.employeeUsername,request.status==='approved'?'تمت الموافقة على طلبك':'تم رفض طلبك',`${request.type==='advance'?'طلب السلفة':'طلب الإجازة'} أصبح ${requestStatusLabels[request.status]}.`,request.id)});updateNotificationCenter()}
    function loadNotifications(){try{let saved=JSON.parse(localStorage.getItem('dawamNotifications'));return Array.isArray(saved)?saved:[]}catch{return []}}
    function visibleNotifications(){if(!currentUser)return [];let recipient=currentUser.type==='employee'?currentUser.username:currentUser.type;return notifications.filter(notification=>notification.recipient===recipient).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))}
    function saveNotifications(){localStorage.setItem('dawamNotifications',JSON.stringify(notifications));updateNotificationCenter()}
    function notify(recipient,title,message,requestId,type='request'){notifications=loadNotifications();notifications.push({id:`${Date.now()}-${Math.random().toString(36).slice(2,8)}`,recipient,title,message,requestId,type,createdAt:new Date().toISOString(),read:false});saveNotifications()}
    function notifyRequestReviewers(request){let recipients=['manager',...employees.filter(employee=>employee.accountType==='supervisor').map(employee=>employee.username)];recipients.forEach(recipient=>notify(recipient,'طلب جديد من '+request.employeeName,`${request.type==='advance'?'طلب سلفة':'طلب إجازة'} بانتظار المراجعة.`,request.id))}
    function updateNotificationCenter(){let list=visibleNotifications(),unread=list.filter(item=>!item.read).length,badge=document.getElementById('notificationCount'),panel=document.getElementById('notificationPanel');if(badge){badge.textContent=unread>99?'99+':arabic(unread);badge.hidden=unread===0}if(!panel)return;panel.innerHTML=`<div class="notification-panel-head"><div><strong>الإشعارات</strong><span>${arabic(unread)} غير مقروء</span></div><div class="notification-panel-actions">${unread?'<button type="button" data-notification-action="read-all">تحديد الكل كمقروء</button>':''}${list.length?'<button type="button" data-notification-action="clear">مسح الكل</button>':''}</div></div>${list.length?`<div class="notification-list">${list.map(item=>`<button type="button" class="notification-item ${item.read?'read':'unread'}" data-notification-id="${escapeHtml(item.id)}" data-request-id="${escapeHtml(item.requestId||'')}"><span class="notification-item-icon"><i data-lucide="${item.type==='request'?'file-text':'bell'}"></i></span><span class="notification-item-body"><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.message)}</span><time datetime="${escapeHtml(item.createdAt)}">${formatNotificationDate(item.createdAt)}</time></span>${item.read?'':'<span class="notification-unread-dot"></span>'}</button>`).join('')}</div>`:'<div class="notification-empty"><i data-lucide="bell-ring"></i><strong>لا توجد إشعارات</strong><span>ستظهر هنا التحديثات الجديدة.</span></div>'}`;if(window.lucide)lucide.createIcons();bindNotificationEvents()}
    function formatNotificationDate(value){let date=new Date(value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('ar-EG',{dateStyle:'medium',timeStyle:'short'}).format(date)}
    function markNotificationsRead(predicate=()=>true){let changed=false;notifications=loadNotifications().map(item=>{if(item.recipient===(currentUser.type==='employee'?currentUser.username:currentUser.type)&&!item.read&&predicate(item)){changed=true;return {...item,read:true}}return item});if(changed)saveNotifications()}
    function bindNotificationEvents(){let button=document.getElementById('notifBtn'),panel=document.getElementById('notificationPanel');if(!button||!panel)return;button.onclick=()=>{let open=panel.hidden;panel.hidden=!open;button.setAttribute('aria-expanded',String(open))};panel.querySelectorAll('[data-notification-action="read-all"]').forEach(action=>action.onclick=()=>markNotificationsRead());panel.querySelectorAll('[data-notification-action="clear"]').forEach(action=>action.onclick=()=>{let recipient=currentUser.type==='employee'?currentUser.username:currentUser.type;notifications=loadNotifications().filter(item=>item.recipient!==recipient);saveNotifications()});panel.querySelectorAll('[data-notification-id]').forEach(item=>item.onclick=()=>{let id=item.dataset.notificationId,requestId=item.dataset.requestId;markNotificationsRead(notification=>notification.id===id);panel.hidden=true;button.setAttribute('aria-expanded','false');if(currentUser.type==='employee'){render();let target=document.getElementById(`request-${requestId}`);if(target){target.classList.add('notification-highlight');target.scrollIntoView({behavior:'smooth',block:'center'})}}else{activeView='requests';render();let target=document.getElementById(`request-${requestId}`);if(target){target.classList.add('notification-highlight');target.scrollIntoView({behavior:'smooth',block:'center'})}}})}
    function readSession(){try{return JSON.parse(sessionStorage.getItem('dawamSession'))}catch{return null}}
    function dataBackupCard(){return `<section class="view data-backup-view"><div class="section-toolbar"><div><h2 class="panel-title">نسخة بيانات محلية</h2><div class="panel-caption">احفظ بيانات التطبيق في ملف JSON أو استعد نسخة سابقة.</div></div></div><section class="settings-card data-backup-card"><h3>حفظ واستعادة البيانات</h3><p>يشمل ملف database.json بيانات الموظفين والطلبات والإشعارات وإعدادات الشركة وكلمات المرور المحفوظة محلياً. احتفظ به في مكان آمن ولا تشاركه.</p><div class="data-backup-actions"><button class="btn btn-primary" id="exportDataBackup" type="button"><i data-lucide="download"></i>تنزيل ملف database.json</button><button class="btn" id="chooseDataBackup" type="button"><i data-lucide="upload"></i>استعادة ملف بيانات</button><input id="dataBackupFile" type="file" accept=".json,application/json" hidden></div></section></section>`}
    function readDataBackup(){let data={};DATA_STORAGE_KEYS.forEach(key=>{let raw=localStorage.getItem(key);if(['dawamEmployees','dawamRequests','dawamNotifications'].includes(key)){let value=raw===null?[]:JSON.parse(raw);if(!Array.isArray(value))throw new Error('بيانات التطبيق الحالية غير صالحة لإنشاء نسخة احتياطية.');data[key]=value}else data[key]=raw||''});return {format:DATA_BACKUP_FORMAT,version:1,createdAt:new Date().toISOString(),data}}
    function validateDataBackup(backup){if(!backup||backup.format!==DATA_BACKUP_FORMAT||backup.version!==1||!backup.data||typeof backup.data!=='object'||Array.isArray(backup.data))throw new Error('الملف ليس نسخة بيانات صالحة لهذا التطبيق.');let data=backup.data;for(let key of DATA_STORAGE_KEYS)if(!Object.prototype.hasOwnProperty.call(data,key))throw new Error('النسخة غير مكتملة ولا تحتوي على جميع البيانات.');for(let key of ['dawamEmployees','dawamRequests','dawamNotifications'])if(!Array.isArray(data[key])||data[key].some(item=>!item||typeof item!=='object'||Array.isArray(item)))throw new Error('تحتوي النسخة على بيانات غير صالحة.');for(let key of ['dawamAdminPassword','dawamCompany'])if(typeof data[key]!=='string')throw new Error('تحتوي النسخة على إعدادات غير صالحة.');return data}
    function applyDataBackup(backup){let data=validateDataBackup(backup),previous=Object.fromEntries(DATA_STORAGE_KEYS.map(key=>[key,localStorage.getItem(key)]));try{DATA_STORAGE_KEYS.forEach(key=>localStorage.setItem(key,Array.isArray(data[key])?JSON.stringify(data[key]):data[key]))}catch(error){try{DATA_STORAGE_KEYS.forEach(key=>{let value=previous[key];if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value)})}catch(rollbackError){throw new Error(`تعذر حفظ النسخة أو التراجع عن التغييرات: ${rollbackError.message}`)}throw new Error(`تعذر حفظ النسخة: ${error.message}`)}employees=loadEmployees();requests=loadRequests();notifications=loadNotifications();save();render();showToast('تمت استعادة البيانات بنجاح')}
    function exportDataBackup(){try{let backup=readDataBackup(),blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='database.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('تم تنزيل database.json')}catch(error){showToast(error.message||'تعذر إنشاء ملف البيانات')}}
    async function importDataBackup(event){let input=event.currentTarget,file=input.files?.[0];if(!file)return;try{let backup=JSON.parse(await file.text());validateDataBackup(backup);if(!confirm('ستُستبدل البيانات الحالية بالبيانات الموجودة في الملف. هل تريد المتابعة؟'))return;applyDataBackup(backup)}catch(error){showToast(error.message||'تعذر استعادة ملف البيانات')}finally{input.value=''}}
    function save(){localStorage.setItem('dawamEmployees',JSON.stringify(employees));document.getElementById('navEmployeeCount').textContent=arabic(employees.length)}
    function arabic(n){return new Intl.NumberFormat('ar-EG').format(n)}
    function money(n){return new Intl.NumberFormat('ar-EG',{maximumFractionDigits:0}).format(n)+' ج.م'}
    function dateString(){return new Intl.DateTimeFormat('ar-EG',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date())}
    function dayKey(){let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('')}
    function dailyToken(){let seed='DAWAM-'+dayKey()+'-HQ';let hash=0;for(let i=0;i<seed.length;i++)hash=((hash<<5)-hash)+seed.charCodeAt(i)|0;return 'DW-'+Math.abs(hash).toString(36).toUpperCase().padStart(6,'0')}
    function qrUrl(){return 'https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=6&color=17231e&bgcolor=ffffff&data='+encodeURIComponent('DAWAM-ATTENDANCE:'+dayKey()+':'+dailyToken())}
    function initials(name){return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join(' ')}
    function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
    function avatarMarkup(employee,extraClass=''){return employee.photo?`<img class="avatar avatar-photo ${extraClass}" src="${escapeHtml(employee.photo)}" alt="صورة ${escapeHtml(employee.name)}">`:`<div class="avatar ${employee.tone||''} ${extraClass}">${escapeHtml(employee.initials||initials(employee.name))}</div>`}
    function resizeProfilePhoto(file){return new Promise((resolve,reject)=>{if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(new Error('اختر صورة بصيغة JPG أو PNG أو WebP.'));if(file.size>5*1024*1024)return reject(new Error('حجم الصورة يتجاوز ٥ ميغابايت.'));let reader=new FileReader();reader.onerror=()=>reject(new Error('تعذر قراءة الصورة.'));reader.onload=()=>{let image=new Image();image.onerror=()=>reject(new Error('تعذر فتح ملف الصورة.'));image.onload=()=>{let scale=Math.min(1,512/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));let context=canvas.getContext('2d');if(!context)return reject(new Error('تعذر تجهيز الصورة في هذا المتصفح.'));context.drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82))};image.src=String(reader.result)};reader.readAsDataURL(file)})}
    function getStats(){return {total:employees.length,present:employees.filter(e=>e.status==='present').length,late:employees.filter(e=>e.status==='late').length,absent:employees.filter(e=>e.status==='absent').length}}
    function employeeRows(list){if(!list.length)return '<tr><td class="empty-table" colspan="6">لا توجد بيانات موظفين بعد. أضف أول موظف لبدء إدخال البيانات.</td></tr>';return list.map(e=>{let i=employees.indexOf(e);return `<tr><td><div class="employee-cell">${avatarMarkup(e)}<div><div class="employee-name">${escapeHtml(e.name)}</div><div class="employee-role">${escapeHtml(e.role)} · ${e.accountType==='supervisor'?'مشرف':'موظف'}${e.phone?` · ${escapeHtml(e.phone)}`:''}</div></div></div></td><td>${escapeHtml(e.dept)}</td><td><span class="status ${e.status}">${statusLabels[e.status]}</span></td><td style="font-family:'DM Sans',sans-serif">${e.in||'—'}</td><td class="salary">${money(e.salary)}</td><td><button class="text-link" data-employee="${i}" aria-label="عرض ملف ${escapeHtml(e.name)}">الملف</button></td></tr>`}).join('')}
    function tableMarkup(list,options={}){return `<section class="panel table-panel"><div class="table-head"><div><h2 class="panel-title">${options.title||'حالة الحضور اليوم'}</h2><div class="panel-caption">${options.caption||'متابعة مباشرة لفريق العمل'}</div></div><div class="table-tools"><label class="search-box"><i data-lucide="search"></i><input id="tableSearch" placeholder="ابحث عن موظف..." aria-label="ابحث عن موظف"></label>${options.filter?`<button class="filter-btn" id="statusFilter"><i data-lucide="list-filter"></i>${attendanceFilter==='all'?'كل الحالات':statusLabels[attendanceFilter]}<i data-lucide="chevron-down"></i></button>`:''}</div></div><div class="table-scroll"><table><thead><tr><th>الموظف</th><th>القسم</th><th>الحالة</th><th>وقت الحضور</th><th>الراتب الأساسي</th><th></th></tr></thead><tbody id="employeeRows">${employeeRows(list)}</tbody></table></div><div class="table-foot"><span>عرض <b>${arabic(list.length)}</b> من ${arabic(employees.length)} موظف</span><button class="text-link" data-view="employees">عرض جميع الموظفين ←</button></div></section>`}
    function chartMarkup(){return `<svg class="chart-svg" viewBox="0 0 620 180" preserveAspectRatio="none" role="img" aria-label="مخطط حضور الموظفين خلال الأسبوع"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#64a47b" stop-opacity=".2"/><stop offset="1" stop-color="#64a47b" stop-opacity="0"/></linearGradient></defs><line x1="40" y1="25" x2="610" y2="25" class="chart-grid"/><line x1="40" y1="65" x2="610" y2="65" class="chart-grid"/><line x1="40" y1="105" x2="610" y2="105" class="chart-grid"/><line x1="40" y1="145" x2="610" y2="145" class="chart-grid"/><text x="3" y="28" class="chart-label">١٠٠٪</text><text x="9" y="68" class="chart-label">٧٥٪</text><text x="9" y="108" class="chart-label">٥٠٪</text><text x="9" y="148" class="chart-label">٢٥٪</text><path class="chart-fill" d="M50 71 L140 57 L230 65 L320 40 L410 52 L500 34 L590 45 L590 150 L50 150 Z"/><path class="chart-line" d="M50 71 L140 57 L230 65 L320 40 L410 52 L500 34 L590 45"/><circle cx="50" cy="71" r="3.5" class="chart-dot"/><circle cx="140" cy="57" r="3.5" class="chart-dot"/><circle cx="230" cy="65" r="3.5" class="chart-dot"/><circle cx="320" cy="40" r="3.5" class="chart-dot"/><circle cx="410" cy="52" r="3.5" class="chart-dot"/><circle cx="500" cy="34" r="3.5" class="chart-dot"/><circle cx="590" cy="45" r="3.5" class="chart-dot"/><text x="42" y="169" class="chart-label">السبت</text><text x="129" y="169" class="chart-label">الأحد</text><text x="216" y="169" class="chart-label">الإثنين</text><text x="308" y="169" class="chart-label">الثلاثاء</text><text x="399" y="169" class="chart-label">الأربعاء</text><text x="489" y="169" class="chart-label">الخميس</text><text x="578" y="169" class="chart-label">الجمعة</text></svg>`}
    function qrPanel(){return `<section class="panel attendance-panel"><div class="panel-head"><div><h2 class="panel-title">رمز الحضور اليومي</h2><div class="panel-caption">امسح الرمز لتسجيل الحضور والانصراف</div></div><span class="status present">نشط</span></div><div class="qr-box"><img src="${qrUrl()}" alt="رمز QR اليومي لتسجيل الحضور"></div><div class="qr-code">${dailyToken()}</div><p class="qr-note">يتجدد الرمز تلقائياً كل يوم</p><div class="qr-controls"><button class="btn btn-soft" id="downloadQr"><i data-lucide="download"></i>تنزيل الرمز</button><button class="btn" id="manualAttendance"><i data-lucide="user-check"></i>تسجيل يدوي</button></div></section>`}
    function statsMarkup(){let s=getStats();return `<div class="stats-grid"><article class="stat-card"><div class="stat-top"><span class="stat-label">إجمالي الموظفين</span><span class="stat-icon"><i data-lucide="users-round"></i></span></div><div class="stat-value">${arabic(s.total)}</div><div class="stat-foot">فريق العمل المسجل</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">حاضرون اليوم</span><span class="stat-icon" style="background:#e7f3eb"><i data-lucide="user-check"></i></span></div><div class="stat-value">${arabic(s.present)}</div><div class="stat-foot"><strong>${arabic(Math.round(s.present/Math.max(1,s.total)*100))}٪</strong> من إجمالي الفريق</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">تأخر اليوم</span><span class="stat-icon" style="background:#fbf3e4;color:#a27220"><i data-lucide="clock-3"></i></span></div><div class="stat-value">${arabic(s.late)}</div><div class="stat-foot">يحتاجون إلى متابعة</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">غياب اليوم</span><span class="stat-icon" style="background:#faece8;color:#a74b3a"><i data-lucide="user-round-x"></i></span></div><div class="stat-value">${arabic(s.absent)}</div><div class="stat-foot">لا يشمل الإجازات المسجلة</div></article></div>`}
    function renderOverview(){let list=employees.slice(0,5);return `<section class="view"><div class="welcome"><div><h2>صباح الخير، محمد 👋</h2><p>إليك ملخص فريقك اليوم، <span>${dateString()}</span></p></div><div class="actions"><button class="btn" data-view="reports"><i data-lucide="file-bar-chart"></i>التقارير</button><button class="btn btn-primary" id="addEmployee"><i data-lucide="plus"></i>إضافة موظف</button></div></div>${statsMarkup()}<div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2 class="panel-title">معدل الحضور</h2><div class="panel-caption">نسبة حضور الفريق خلال هذا الأسبوع</div></div><div class="legend"><i></i>نسبة الحضور</div></div><div class="chart-wrap">${employees.length?chartMarkup():'<p class="chart-empty">أضف موظفين لعرض إحصائيات الحضور.</p>'}</div></section>${qrPanel()}</div>${tableMarkup(list)}</section>`}
    function renderEmployees(){return `<section class="view"><div class="section-toolbar"><div><h2 class="panel-title">قائمة الموظفين</h2><div class="panel-caption">إدارة بيانات الفريق وحساباتهم ومواعيد عملهم</div></div><div class="toolbar-left"><button class="btn" id="exportEmployees"><i data-lucide="download"></i>تصدير</button><button class="btn btn-primary" id="addEmployee"><i data-lucide="plus"></i>إضافة موظف</button></div></div>${tableMarkup(employees,{title:'جميع الموظفين',caption:'بيانات الموظفين وحالة دوامهم اليوم',filter:true})}</section>`}
    function renderAttendance(){let rows=attendanceFilter==='all'?employees:employees.filter(e=>e.status===attendanceFilter);return `<section class="view"><div class="section-toolbar"><div><h2 class="panel-title">سجل الحضور اليومي</h2><div class="panel-caption">${dateString()} · إدارة الحضور والانصراف للفريق</div></div><div class="toolbar-left"><button class="btn" id="downloadQr"><i data-lucide="scan-qr-code"></i>رمز اليوم</button><button class="btn btn-primary" id="manualAttendance"><i data-lucide="user-check"></i>تسجيل يدوي</button></div></div>${statsMarkup()}${tableMarkup(rows,{title:'سجل اليوم',caption:'سجل الحضور والانصراف حسب الحالة',filter:true})}</section>`}
    function renderSchedules(){let depts=[...new Set(employees.map(e=>e.dept))];return `<section class="view"><div class="section-toolbar"><div><h2 class="panel-title">مواعيد العمل</h2><div class="panel-caption">إعداد ساعات الدوام الرسمية لكل قسم</div></div><button class="btn btn-primary" id="editSchedule"><i data-lucide="clock-3"></i>تعديل المواعيد</button></div><div class="schedule-grid">${depts.map((d,i)=>{let e=employees.find(x=>x.dept===d);return `<article class="schedule-card"><h3>${escapeHtml(d)}</h3><p>${arabic(employees.filter(x=>x.dept===d).length)} موظفين · ${i===2?'نظام مرن':'دوام كامل'}</p><div class="time-row"><span>بداية الدوام</span><strong>${e.start}</strong></div><div class="time-row" style="margin-top:9px"><span>نهاية الدوام</span><strong>${e.end}</strong></div></article>`}).join('')}</div></section>`}
    function renderPayroll(){let total=employees.reduce((a,e)=>a+Number(e.salary||0),0),bonus=employees.reduce((a,e)=>a+Number(e.bonus||0),0);return `<section class="view"><div class="section-toolbar"><div><h2 class="panel-title">الرواتب والمكافآت</h2><div class="panel-caption">ملخص تقديري للرواتب الشهرية والمكافآت</div></div><button class="btn btn-primary" id="exportPayroll"><i data-lucide="download"></i>تصدير كشف الرواتب</button></div><div class="payroll-summary"><article class="stat-card"><div class="stat-label">إجمالي الرواتب الأساسية</div><div class="stat-value">${money(total)}</div><div class="stat-foot">قبل إضافة المكافآت والخصومات</div></article><article class="stat-card"><div class="stat-label">إجمالي المكافآت</div><div class="stat-value">${money(bonus)}</div><div class="stat-foot">مكافآت شهرية مسجلة</div></article><article class="stat-card"><div class="stat-label">صافي المستحقات التقديري</div><div class="stat-value">${money(total+bonus)}</div><div class="stat-foot">الراتب الأساسي + المكافأة</div></article></div><section class="panel table-panel"><div class="table-head"><div><h2 class="panel-title">تفاصيل الرواتب</h2><div class="panel-caption">القيم بالجنيه المصري</div></div><label class="search-box"><i data-lucide="search"></i><input id="tableSearch" placeholder="ابحث عن موظف..." aria-label="ابحث عن موظف"></label></div><div class="table-scroll"><table><thead><tr><th>الموظف</th><th>القسم</th><th>الراتب الأساسي</th><th>المكافأة</th><th>الخصومات</th><th>الصافي التقديري</th></tr></thead><tbody id="payrollRows">${employees.map((e,i)=>`<tr><td><div class="employee-cell"><div class="avatar ${e.tone||''}">${escapeHtml(e.initials||initials(e.name))}</div><div><div class="employee-name">${escapeHtml(e.name)}</div><div class="employee-role">${escapeHtml(e.role)}</div></div></div></td><td>${escapeHtml(e.dept)}</td><td class="salary">${money(e.salary)}</td><td style="color:var(--green)">${money(e.bonus||0)}</td><td>${money(e.deduction||0)}</td><td class="salary">${money(Number(e.salary)+Number(e.bonus||0)-Number(e.deduction||0))}</td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>كشف رواتب ${arabic(employees.length)} موظف</span><span>يتم تحديث الإجماليات تلقائياً</span></div></section></section>`}
    function renderReports(){let s=getStats(),total=employees.reduce((a,e)=>a+Number(e.salary||0)+Number(e.bonus||0),0);return `<section class="view"><div class="section-toolbar"><div><h2 class="panel-title">التقارير والإحصائيات</h2><div class="panel-caption">ملخص أداء الحضور وتكاليف فريق العمل</div></div><button class="btn" id="printReport"><i data-lucide="printer"></i>طباعة التقرير</button></div><div class="stats-grid"><article class="stat-card"><div class="stat-label">معدل الحضور اليوم</div><div class="stat-value">${arabic(Math.round(s.present/Math.max(1,s.total)*100))}٪</div><div class="stat-foot">من إجمالي الموظفين</div></article><article class="stat-card"><div class="stat-label">إجمالي ساعات الدوام المجدولة</div><div class="stat-value">${arabic(employees.length*8)} <small style="font-size:12px">ساعة</small></div><div class="stat-foot">بمعدل ٨ ساعات لكل موظف</div></article><article class="stat-card"><div class="stat-label">التكلفة الشهرية التقديرية</div><div class="stat-value" style="font-size:20px">${money(total)}</div><div class="stat-foot">رواتب ومكافآت الفريق</div></article><article class="stat-card"><div class="stat-label">الالتزام بالمواعيد</div><div class="stat-value">${arabic(Math.round((s.present/Math.max(1,s.present+s.late))*100))}٪</div><div class="stat-foot">للموظفين المسجلين اليوم</div></article></div><div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2 class="panel-title">معدل الحضور الأسبوعي</h2><div class="panel-caption">مقارنة يومية لأداء الحضور</div></div></div><div class="chart-wrap">${employees.length?chartMarkup():'<p class="chart-empty">أضف موظفين لعرض إحصائيات الحضور.</p>'}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">ملخص الحالات</h2><div class="panel-caption">حالة الموظفين لهذا اليوم</div></div></div>${[['حاضر',s.present,'present'],['متأخر',s.late,'late'],['غائب',s.absent,'absent'],['إجازة',employees.filter(e=>e.status==='leave').length,'leave']].map(x=>`<div style="display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid #eff0ec"><span class="status ${x[2]}">${x[0]}</span><strong style="font-family:'DM Sans',sans-serif">${arabic(x[1])}</strong></div>`).join('')}</section></div></section>`}
    function renderSettings(){return `<section class="view"><div class="section-toolbar"><div><h2 class="panel-title">إعدادات النظام</h2><div class="panel-caption">إدارة تفضيلات حسابك ومواعيد العمل الافتراضية</div></div></div><div class="settings-grid"><section class="settings-card"><h3>مواعيد العمل الافتراضية</h3><p>تُطبق هذه المواعيد عند إضافة موظف جديد. يمكن تخصيص مواعيد كل موظف لاحقاً.</p><div class="form-row"><div class="field"><label>بداية الدوام</label><input id="defaultStart" type="time" value="09:00"></div><div class="field"><label>نهاية الدوام</label><input id="defaultEnd" type="time" value="17:00"></div></div><button class="btn btn-primary" id="saveDefaults">حفظ المواعيد</button></section><section class="settings-card"><h3>تغيير كلمة المرور</h3><p>غيّر كلمة مرور حساب المدير للحفاظ على أمان بيانات الموظفين.</p><div class="field"><label>كلمة المرور الحالية</label><input id="oldPassword" type="password" placeholder="أدخل كلمة المرور الحالية"></div><div class="form-row"><div class="field"><label>كلمة المرور الجديدة</label><input id="newPassword" type="password" placeholder="٨ أحرف على الأقل"></div><div class="field"><label>تأكيد كلمة المرور</label><input id="confirmPassword" type="password" placeholder="أعد كتابة كلمة المرور"></div></div><button class="btn btn-primary" id="changePassword">تحديث كلمة المرور</button></section><section class="settings-card"><h3>بيانات الشركة</h3><p>تظهر هذه البيانات في تقارير الحضور وسجلات الموظفين.</p><div class="field"><label>اسم الشركة</label><input id="companyName" value="شركة الأفق للتقنية"></div><div class="field"><label>العملة</label><select><option>الجنيه المصري (ج.م)</option><option>الريال السعودي (ر.س)</option><option>الدرهم الإماراتي (د.إ)</option></select></div><button class="btn" id="saveCompany">حفظ البيانات</button></section><section class="settings-card"><h3>رمز الحضور اليومي</h3><p>رمز QR آمن يتغير يومياً، ويمكن للموظفين مسحه لتسجيل الحضور. الرمز الحالي:</p><div style="display:flex;align-items:center;gap:12px"><div class="avatar" style="border-radius:9px"><i data-lucide="scan-qr-code"></i></div><div><strong style="font-family:'DM Sans',sans-serif">${dailyToken()}</strong><div class="panel-caption">تجديد تلقائي عند منتصف الليل</div></div></div></section></div></section>`}
    const renderers={overview:renderOverview,employees:renderEmployees,attendance:renderAttendance,schedules:renderSchedules,payroll:renderPayroll,requests:renderRequests,reports:renderReports,settings:()=>renderSettings()+dataBackupCard()};
    function submitLogin(event){event.preventDefault();let username=document.getElementById('loginUsername').value.trim(),password=document.getElementById('loginPassword').value,error=document.getElementById('loginError');let employee=employees.find(e=>e.username===username&&e.password===password);if(username.toUpperCase()==='TITO'&&password===localStorage.getItem('dawamAdminPassword'))currentUser={type:'manager'};else if(employee)currentUser={type:employee.accountType==='supervisor'?'supervisor':'employee',name:employee.name,username:employee.username};else{error.textContent='اسم المستخدم أو كلمة المرور غير صحيحة.';error.classList.add('show');return}error.textContent='';error.classList.remove('show');closeNotificationPanel();sessionStorage.setItem('dawamSession',JSON.stringify(currentUser));render()}
    function renderEmployeePortal(){let employee=employees.find(e=>e.username===currentUser.username);if(!employee)return '<section class="employee-portal"><div class="portal-card">تعذر العثور على بيانات حسابك. سجّل الخروج وتواصل مع المدير.</div></section>';let ownRequests=requests.filter(request=>request.employeeUsername===employee.username);return `<section class="employee-portal"><header class="portal-head"><div><h2>مرحباً، ${escapeHtml(employee.name)}</h2><p>هذه بيانات حسابك الشخصي.</p></div><button class="btn" id="employeeLogout">تسجيل الخروج</button></header><div class="portal-grid"><article class="portal-card"><h3>حالة الحضور اليوم</h3><span class="status ${employee.status}">${statusLabels[employee.status]||'غير مسجل'}</span><div class="portal-meta">الحضور: ${escapeHtml(employee.in||'—')} · الانصراف: ${escapeHtml(employee.out||'—')}</div></article><article class="portal-card"><h3>مواعيد العمل</h3><div class="portal-value">${escapeHtml(employee.start||'—')} – ${escapeHtml(employee.end||'—')}</div><div class="portal-meta">${escapeHtml(employee.dept||'')}</div></article></div><section class="portal-card portal-request-card"><h3>تقديم طلب سلفة أو إجازة</h3><form id="employeeRequestForm"><div class="field"><label for="requestType">نوع الطلب</label><select id="requestType" name="type"><option value="advance">سلفة مالية</option><option value="leave">إجازة</option></select></div><div class="form-row request-advance-fields"><div class="field"><label for="requestAmount">مبلغ السلفة (ج.م)</label><input id="requestAmount" name="amount" type="number" min="1" step="0.01" required></div><div class="field"><label for="requestRepaymentMonths">مدة السداد (بالأشهر)</label><input id="requestRepaymentMonths" name="repaymentMonths" type="number" min="1" max="60" value="1" required></div></div><div class="form-row request-leave-fields" hidden><div class="field"><label for="requestStartDate">من تاريخ</label><input id="requestStartDate" name="startDate" type="date" disabled></div><div class="field"><label for="requestEndDate">إلى تاريخ</label><input id="requestEndDate" name="endDate" type="date" disabled></div></div><div class="field"><label for="requestReason">سبب الطلب</label><textarea id="requestReason" name="reason" rows="3" maxlength="500" required></textarea></div><button class="btn btn-primary" type="submit">إرسال الطلب</button></form></section><section class="portal-card portal-requests"><h3>طلباتي السابقة</h3>${employeeRequestRows(ownRequests)}</section></section>`}
    function employeeRequestRows(list){if(!list.length)return '<p class="portal-meta">لم ترسل أي طلبات بعد.</p>';return `<div class="request-list">${list.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(request=>`<article class="request-item" id="request-${escapeHtml(request.id)}"><div class="request-item-head"><strong>${request.type==='advance'?'سلفة مالية':'إجازة'}</strong><span class="request-status ${request.status}">${requestStatusLabels[request.status]||'قيد المراجعة'}</span></div><p>${request.type==='advance'?`المبلغ: ${money(request.amount)} · السداد: ${arabic(request.repaymentMonths)} شهر`:`من ${escapeHtml(request.startDate)} إلى ${escapeHtml(request.endDate)}`}</p><p>${escapeHtml(request.reason)}</p></article>`).join('')}</div>`}
    function employeeProfileCard(employee){let details=[['المسمى الوظيفي',employee.role],['القسم',employee.dept],['الهاتف',employee.phone],['البريد الإلكتروني',employee.email],['العنوان',employee.address],['تاريخ التعيين',employee.hireDate],['جهة اتصال الطوارئ',employee.emergencyContact],['هاتف الطوارئ',employee.emergencyPhone]].filter(([,value])=>value);return `<section class="portal-card employee-profile-card"><div class="employee-profile-heading">${avatarMarkup(employee,'employee-profile-avatar')}<div><h3>الملف الشخصي</h3><strong>${escapeHtml(employee.name)}</strong><span>${employee.accountType==='supervisor'?'مشرف':'موظف'}</span></div><button class="btn btn-soft" id="editMyProfile">تعديل بيانات التواصل</button></div><div class="employee-profile-details">${details.length?details.map(([label,value])=>`<div><span>${label}</span><strong>${escapeHtml(value)}</strong></div>`).join(''):'<p class="portal-meta">أضف بيانات التواصل لإكمال ملفك الشخصي.</p>'}</div></section>`}
    function bindEmployeePortal(){let employee=employees.find(item=>item.username===currentUser.username),requestCard=document.querySelector('.portal-request-card');if(employee&&requestCard){requestCard.insertAdjacentHTML('beforebegin',employeeProfileCard(employee));document.getElementById('editMyProfile').onclick=openEmployeeContactEditor}let button=document.getElementById('employeeLogout');if(button)button.onclick=logout;let form=document.getElementById('employeeRequestForm');if(form){let type=form.elements.type,advanceFields=form.querySelector('.request-advance-fields'),leaveFields=form.querySelector('.request-leave-fields'),amount=form.elements.amount,repayment=form.elements.repaymentMonths,startDate=form.elements.startDate,endDate=form.elements.endDate;type.onchange=()=>{let isLeave=type.value==='leave';advanceFields.hidden=isLeave;leaveFields.hidden=!isLeave;amount.disabled=isLeave;repayment.disabled=isLeave;amount.required=!isLeave;repayment.required=!isLeave;startDate.disabled=!isLeave;endDate.disabled=!isLeave;startDate.required=isLeave;endDate.required=isLeave};form.onsubmit=event=>{event.preventDefault();let data=new FormData(form),isAdvance=data.get('type')==='advance';if(!isAdvance&&data.get('endDate')<data.get('startDate'))return showToast('تاريخ نهاية الإجازة يجب أن يكون بعد تاريخ بدايتها');requests.push({id:`${Date.now()}-${Math.random().toString(36).slice(2,8)}`,employeeUsername:currentUser.username,employeeName:employeeName(),type:isAdvance?'advance':'leave',amount:isAdvance?Number(data.get('amount')):null,repaymentMonths:isAdvance?Number(data.get('repaymentMonths')):null,startDate:isAdvance?'':data.get('startDate'),endDate:isAdvance?'':data.get('endDate'),reason:data.get('reason').trim(),status:'pending',createdAt:new Date().toISOString()});saveRequests();render();showToast('تم إرسال الطلب إلى المدير والمشرف')};type.onchange()}}
    function changeCurrentPassword(){let currentPassword=localStorage.getItem('dawamAdminPassword')||'TITO123456',oldPassword=document.getElementById('oldPassword').value,newPassword=document.getElementById('newPassword').value,confirmPassword=document.getElementById('confirmPassword').value;if(oldPassword!==currentPassword)return showToast('كلمة المرور الحالية غير صحيحة');if(newPassword.length<8)return showToast('كلمة المرور الجديدة يجب ألا تقل عن ٨ أحرف');if(newPassword!==confirmPassword)return showToast('كلمتا المرور الجديدتان غير متطابقتين');localStorage.setItem('dawamAdminPassword',newPassword);document.getElementById('oldPassword').value='';document.getElementById('newPassword').value='';document.getElementById('confirmPassword').value='';showToast('تم تحديث كلمة المرور بنجاح')}
    function employeeName(){let employee=employees.find(e=>e.username===currentUser.username);return employee?employee.name:''}
    function renderRequests(){let ordered=requests.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return `<section class="view"><div class="section-toolbar"><div><h2 class="panel-title">طلبات السلف والإجازات</h2><div class="panel-caption">مراجعة طلبات الموظفين واتخاذ القرار</div></div><span class="status pending">${arabic(requests.filter(request=>request.status==='pending').length)} قيد المراجعة</span></div>${ordered.length?`<div class="request-list manager-request-list">${ordered.map(request=>`<article class="panel request-item" id="request-${escapeHtml(request.id)}"><div class="request-item-head"><div><strong>${escapeHtml(request.employeeName)}</strong><span class="request-type">${request.type==='advance'?'سلفة مالية':'إجازة'}</span></div><span class="request-status ${request.status}">${requestStatusLabels[request.status]||'قيد المراجعة'}</span></div><p>${request.type==='advance'?`المبلغ المطلوب: <strong>${money(request.amount)}</strong> · مدة السداد: ${arabic(request.repaymentMonths)} شهر`:`الإجازة من <strong>${escapeHtml(request.startDate)}</strong> إلى <strong>${escapeHtml(request.endDate)}</strong>`}</p><p>${escapeHtml(request.reason)}</p><div class="request-item-foot"><span class="panel-caption">تاريخ الطلب: ${new Intl.DateTimeFormat('ar-EG',{dateStyle:'medium'}).format(new Date(request.createdAt))}</span>${request.status==='pending'?`<div class="request-actions"><button class="btn btn-primary" data-request-action="approved" data-request-id="${escapeHtml(request.id)}">قبول</button><button class="btn btn-danger" data-request-action="rejected" data-request-id="${escapeHtml(request.id)}">رفض</button></div>`:''}</div></article>`).join('')}</div>`:'<section class="panel empty-requests">لا توجد طلبات حتى الآن.</section>'}</section>`}
    function reviewRequest(id,status){if(!['approved','rejected'].includes(status))return;let request=requests.find(item=>item.id===id);if(!request||request.status!=='pending')return;request.status=status;request.reviewedAt=new Date().toISOString();request.reviewedBy=currentUser.type;saveRequests();render();showToast(status==='approved'?'تم قبول الطلب':'تم رفض الطلب')}
    function closeNotificationPanel(){let panel=document.getElementById('notificationPanel'),button=document.getElementById('notifBtn');if(panel)panel.hidden=true;if(button)button.setAttribute('aria-expanded','false')}
    function logout(){closeNotificationPanel();currentUser=null;sessionStorage.removeItem('dawamSession');document.getElementById('loginUsername').value='';document.getElementById('loginPassword').value='';activeView='overview';render()}
    function render(){let login=document.getElementById('loginScreen'),app=document.getElementById('appRoot');login.classList.toggle('hidden',Boolean(currentUser));app.classList.toggle('auth-locked',!currentUser);app.classList.toggle('employee-mode',currentUser?.type==='employee');if(!currentUser)return;let profileName=currentUser.type==='manager'?'TITO':currentUser.name;document.getElementById('profileName').textContent=profileName;document.getElementById('profileRole').textContent=currentUser.type==='manager'?'مدير النظام':currentUser.type==='supervisor'?'مشرف النظام':'موظف';document.getElementById('profileAvatar').textContent=initials(profileName);updateNotificationCenter();bindNotificationEvents();if(currentUser.type==='employee'){document.getElementById('pageTitle').textContent='بوابتي';document.getElementById('crumbTitle').textContent='بوابتي';document.getElementById('viewRoot').innerHTML=renderEmployeePortal();if(window.lucide)lucide.createIcons();bindEmployeePortal();return}let title=viewTitles[activeView];document.getElementById('pageTitle').textContent=title;document.getElementById('crumbTitle').textContent=title;document.getElementById('viewRoot').innerHTML=renderers[activeView]();document.querySelectorAll('.nav-btn[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===activeView));if(window.lucide)lucide.createIcons();bindViewEvents()}
    function showToast(message){let t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2600)}
    function openModal(title,content,onSubmit){let b=document.getElementById('modalBackdrop'),c=document.getElementById('modalContent');c.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close-btn" id="closeModal" aria-label="إغلاق"><i data-lucide="x"></i></button></div>${content}`;b.classList.add('show');if(window.lucide)lucide.createIcons();document.getElementById('closeModal').onclick=closeModal;b.onclick=e=>{if(e.target===b)closeModal()};let form=c.querySelector('form');if(!form)return;bindProfilePhoto(form);form.onsubmit=async event=>{event.preventDefault();let data=new FormData(form),photo=form.elements.photoFile?.files[0];try{data.set('photoData',photo?await resizeProfilePhoto(photo):'');onSubmit(data)}catch(error){showToast(error.message||'تعذر حفظ صورة الموظف.')}}}
    function profilePhotoFields(employee){let fallback=employee.photo?`<img class="profile-photo-preview" src="${escapeHtml(employee.photo)}" alt="صورة الموظف">`:`<div class="profile-photo-fallback">${escapeHtml(employee.initials||initials(employee.name||'موظف'))}</div>`;return `<div class="profile-photo-field"><div class="profile-photo-preview-wrap" id="profilePhotoPreview" data-avatar-name="${escapeHtml(employee.name||'موظف')}" data-avatar-initials="${escapeHtml(employee.initials||initials(employee.name||'موظف'))}">${fallback}</div><div class="profile-photo-controls"><label class="btn btn-soft profile-photo-button" for="employeePhoto">اختيار صورة</label><input id="employeePhoto" name="photoFile" type="file" accept="image/jpeg,image/png,image/webp"><input name="photoAction" type="hidden" value="preserve"><button class="text-link" type="button" id="removeEmployeePhoto" ${employee.photo?'':'disabled'}>إزالة الصورة</button><span class="field-hint">صورة JPG أو PNG أو WebP، بحد أقصى ٥ ميغابايت.</span></div></div>`}
    function bindProfilePhoto(form){let input=form.elements.photoFile,preview=form.querySelector('#profilePhotoPreview'),remove=form.querySelector('#removeEmployeePhoto'),action=form.elements.photoAction;if(!input||!preview||!remove||!action)return;input.onchange=()=>{let file=input.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){input.value='';showToast(file.size>5*1024*1024?'حجم الصورة يتجاوز ٥ ميغابايت.':'اختر صورة بصيغة JPG أو PNG أو WebP.');return}let reader=new FileReader();reader.onerror=()=>showToast('تعذر قراءة الصورة.');reader.onload=()=>{preview.innerHTML=`<img class="profile-photo-preview" src="${String(reader.result)}" alt="معاينة صورة الموظف">`;action.value='replace';remove.disabled=false};reader.readAsDataURL(file)};remove.onclick=()=>{input.value='';action.value='remove';preview.innerHTML=`<div class="profile-photo-fallback">${escapeHtml(preview.dataset.avatarInitials)}</div>`;remove.disabled=true}}
    function employeeProfileFields(employee,isNew){let e=employee||{},accountType=e.accountType||'employee';return `${profilePhotoFields(e)}<div class="form-row"><div class="field"><label>الاسم الكامل</label><input name="name" value="${escapeHtml(e.name||'')}" autocomplete="name" required></div><div class="field"><label>المسمى الوظيفي</label><input name="role" value="${escapeHtml(e.role||'')}" required></div></div><div class="form-row"><div class="field"><label>اسم المستخدم</label><input name="username" value="${escapeHtml(e.username||'')}" autocomplete="username" required></div><div class="field"><label>نوع الحساب</label><select name="accountType"><option value="employee" ${accountType==='employee'?'selected':''}>موظف</option><option value="supervisor" ${accountType==='supervisor'?'selected':''}>مشرف</option></select></div></div><div class="form-row"><div class="field"><label>رقم الهاتف</label><input name="phone" type="tel" value="${escapeHtml(e.phone||'')}" autocomplete="tel" placeholder="+20 1xxxxxxxxx"></div><div class="field"><label>البريد الإلكتروني</label><input name="email" type="email" value="${escapeHtml(e.email||'')}" autocomplete="email"></div></div><div class="form-row"><div class="field"><label>القسم</label><input name="dept" value="${escapeHtml(e.dept||'')}" required></div><div class="field"><label>تاريخ التعيين</label><input name="hireDate" type="date" value="${escapeHtml(e.hireDate||'')}"></div></div><div class="field"><label>العنوان</label><input name="address" value="${escapeHtml(e.address||'')}" autocomplete="street-address"></div><div class="form-row"><div class="field"><label>اسم جهة اتصال للطوارئ</label><input name="emergencyContact" value="${escapeHtml(e.emergencyContact||'')}"></div><div class="field"><label>هاتف الطوارئ</label><input name="emergencyPhone" type="tel" value="${escapeHtml(e.emergencyPhone||'')}"></div></div><div class="form-row"><div class="field"><label>الراتب الأساسي (ج.م)</label><input name="salary" type="number" min="0" step="0.01" value="${escapeHtml(e.salary??'')}" required></div><div class="field"><label>المكافأة الشهرية</label><input name="bonus" type="number" min="0" step="0.01" value="${escapeHtml(e.bonus??0)}"></div></div><div class="form-row"><div class="field"><label>بداية الدوام</label><input name="start" type="time" value="${escapeHtml(e.start||'09:00')}"></div><div class="field"><label>نهاية الدوام</label><input name="end" type="time" value="${escapeHtml(e.end||'17:00')}"></div></div><div class="field"><label>${isNew?'كلمة المرور الأولية':'تغيير كلمة المرور (اختياري)'}</label><input name="password" type="password" autocomplete="new-password" ${isNew?'required':''}></div>`}
    function openEmployeeEditor(index=null){let employee=index===null?null:employees[index],isNew=!employee,title=isNew?'إضافة موظف جديد':'الملف الكامل للموظف';openModal(title,`<form class="employee-editor-form">${employeeProfileFields(employee,isNew)}<div class="modal-actions"><button class="btn btn-primary" type="submit">${isNew?'إنشاء الحساب':'حفظ بيانات الموظف'}</button><button class="btn" type="button" id="cancelModal">إلغاء</button></div></form>`,data=>{let username=data.get('username').trim();if(employees.some((item,i)=>item.username===username&&i!==index))return showToast('اسم المستخدم مستخدم بالفعل');let name=data.get('name').trim(),oldUsername=employee?.username;let profile={name,username,role:data.get('role').trim(),accountType:data.get('accountType'),phone:data.get('phone').trim(),email:data.get('email').trim(),dept:data.get('dept').trim(),hireDate:data.get('hireDate'),address:data.get('address').trim(),emergencyContact:data.get('emergencyContact').trim(),emergencyPhone:data.get('emergencyPhone').trim(),salary:Number(data.get('salary')),bonus:Number(data.get('bonus')||0),start:data.get('start'),end:data.get('end'),initials:initials(name),photo:data.get('photoAction')==='remove'?'':data.get('photoData')||(employee?.photo||''),tone:employee?.tone||'avatar-sky'};if(data.get('password'))profile.password=data.get('password');if(isNew){profile.status='absent';profile.in='—';profile.out='—';employees.unshift(profile)}else{Object.assign(employee,profile);if(oldUsername!==username){requests.forEach(request=>{if(request.employeeUsername===oldUsername)request.employeeUsername=username});localStorage.setItem('dawamRequests',JSON.stringify(requests));notifications=loadNotifications().map(item=>item.recipient===oldUsername?{...item,recipient:username}:item);saveNotifications()}}save();closeModal();render();showToast(isNew?'تم إنشاء حساب الموظف':'تم تحديث ملف الموظف')});document.getElementById('cancelModal').onclick=closeModal}
    function addEmployeeModal(){openEmployeeEditor()}
    function accountModal(index){openEmployeeEditor(index)}
    function openEmployeeContactEditor(){let employee=employees.find(item=>item.username===currentUser.username);if(!employee)return;openModal('تحديث بيانات التواصل',`<form>${profilePhotoFields(employee)}<div class="form-row"><div class="field"><label>رقم الهاتف</label><input name="phone" type="tel" value="${escapeHtml(employee.phone||'')}" autocomplete="tel"></div><div class="field"><label>البريد الإلكتروني</label><input name="email" type="email" value="${escapeHtml(employee.email||'')}" autocomplete="email"></div></div><div class="field"><label>العنوان</label><input name="address" value="${escapeHtml(employee.address||'')}" autocomplete="street-address"></div><div class="form-row"><div class="field"><label>اسم جهة اتصال للطوارئ</label><input name="emergencyContact" value="${escapeHtml(employee.emergencyContact||'')}"></div><div class="field"><label>هاتف الطوارئ</label><input name="emergencyPhone" type="tel" value="${escapeHtml(employee.emergencyPhone||'')}"></div></div><div class="modal-actions"><button class="btn btn-primary" type="submit">حفظ بيانات التواصل</button><button class="btn" type="button" id="cancelModal">إلغاء</button></div></form>`,data=>{employee.phone=data.get('phone').trim();employee.email=data.get('email').trim();employee.address=data.get('address').trim();employee.emergencyContact=data.get('emergencyContact').trim();employee.emergencyPhone=data.get('emergencyPhone').trim();employee.photo=data.get('photoAction')==='remove'?'':data.get('photoData')||(employee.photo||'');save();closeModal();render();showToast('تم تحديث بيانات التواصل')});document.getElementById('cancelModal').onclick=closeModal}
    function closeModal(){document.getElementById('modalBackdrop').classList.remove('show')}
    function addEmployeeModalLegacy(){openModal('إضافة موظف جديد',`<form><div class="form-row"><div class="field"><label>اسم الموظف</label><input name="name" required placeholder="الاسم بالكامل"></div><div class="field"><label>المسمى الوظيفي</label><input name="role" required placeholder="مثال: محاسب"></div></div><div class="form-row"><div class="field"><label>اسم المستخدم</label><input name="username" required placeholder="مثال: ahmed.m" autocomplete="off"></div><div class="field"><label>نوع الحساب</label><select name="accountType"><option value="employee">موظف</option><option value="supervisor">مشرف</option></select></div></div><div class="form-row"><div class="field"><label>القسم</label><select name="dept"><option>الإدارة</option><option>التصميم</option><option>التسويق</option><option>التقنية</option><option>الموارد البشرية</option><option>المالية</option><option>المبيعات</option></select></div><div class="field"><label>الراتب الأساسي (ج.م)</label><input name="salary" type="number" min="0" required placeholder="12000"></div></div><div class="form-row"><div class="field"><label>المكافأة الشهرية</label><input name="bonus" type="number" min="0" value="0"></div><div class="field"><label>كلمة المرور المؤقتة</label><input name="password" type="password" required placeholder="كلمة مرور أولية"></div></div><div class="form-row"><div class="field"><label>بداية الدوام</label><input name="start" type="time" value="09:00"></div><div class="field"><label>نهاية الدوام</label><input name="end" type="time" value="17:00"></div></div><div class="modal-actions"><button class="btn btn-primary" type="submit">إنشاء الحساب</button><button class="btn" type="button" id="cancelModal">إلغاء</button></div></form>`,fd=>{let username=fd.get('username').trim();if(employees.some(e=>e.username===username))return showToast('اسم المستخدم مستخدم بالفعل');let name=fd.get('name').trim();employees.unshift({name,username,accountType:fd.get('accountType'),role:fd.get('role'),dept:fd.get('dept'),salary:Number(fd.get('salary')),bonus:Number(fd.get('bonus')||0),start:fd.get('start'),end:fd.get('end'),password:fd.get('password'),status:'absent',in:'—',out:'—',initials:initials(name),tone:'avatar-sky'});save();closeModal();render();showToast('تم إنشاء الحساب بنجاح')});document.getElementById('cancelModal').onclick=closeModal}
    function accountModalLegacy(index){let e=employees[index];openModal('إدارة حساب الموظف',`<form><div class="field"><label>الموظف</label><input value="${escapeHtml(e.name)}" disabled></div><div class="form-row"><div class="field"><label>اسم المستخدم</label><input name="username" value="${escapeHtml(e.username)}" required></div><div class="field"><label>نوع الحساب</label><select name="accountType"><option value="employee" ${e.accountType!=='supervisor'?'selected':''}>موظف</option><option value="supervisor" ${e.accountType==='supervisor'?'selected':''}>مشرف</option></select></div></div><div class="field"><label>كلمة مرور جديدة <span style="color:var(--muted)">(اتركها فارغة دون تغيير)</span></label><input name="password" type="password" placeholder="أدخل كلمة مرور جديدة"></div><div class="modal-actions"><button class="btn btn-primary" type="submit">حفظ بيانات الحساب</button><button class="btn" type="button" id="cancelModal">إلغاء</button></div></form>`,fd=>{let username=fd.get('username').trim();if(employees.some((x,i)=>i!==index&&x.username===username))return showToast('اسم المستخدم مستخدم بالفعل');e.username=username;e.accountType=fd.get('accountType');if(fd.get('password'))e.password=fd.get('password');save();closeModal();render();showToast('تم تحديث بيانات الحساب')});document.getElementById('cancelModal').onclick=closeModal}
    function attendanceModal(){let options=employees.map((e,i)=>`<option value="${i}">${escapeHtml(e.name)} · ${statusLabels[e.status]}</option>`).join('');openModal('تسجيل حضور أو انصراف',`<form><div class="field"><label>اختيار الموظف</label><select name="employee">${options}</select></div><div class="field"><label>نوع التسجيل</label><select name="action"><option value="in">تسجيل حضور</option><option value="out">تسجيل انصراف</option></select></div><div class="field"><label>الوقت</label><input name="time" type="time" value="${new Date().toTimeString().slice(0,5)}" required></div><div class="modal-actions"><button class="btn btn-primary" type="submit">تأكيد التسجيل</button><button class="btn" type="button" id="cancelModal">إلغاء</button></div></form>`,fd=>{let e=employees[Number(fd.get('employee'))],action=fd.get('action');if(action==='in'){e.in=fd.get('time');e.status=fd.get('time')>e.start?'late':'present'}else{e.out=fd.get('time');if(e.status==='absent')e.status='present'}save();closeModal();render();showToast(action==='in'?'تم تسجيل الحضور بنجاح':'تم تسجيل الانصراف بنجاح')});document.getElementById('cancelModal').onclick=closeModal}
    function scheduleModal(){openModal('تعديل مواعيد العمل',`<form><div class="field"><label>القسم</label><select name="dept">${[...new Set(employees.map(e=>e.dept))].map(d=>`<option>${escapeHtml(d)}</option>`).join('')}</select></div><div class="form-row"><div class="field"><label>بداية الدوام</label><input name="start" type="time" value="09:00"></div><div class="field"><label>نهاية الدوام</label><input name="end" type="time" value="17:00"></div></div><div class="modal-actions"><button class="btn btn-primary" type="submit">حفظ المواعيد</button><button class="btn" type="button" id="cancelModal">إلغاء</button></div></form>`,fd=>{employees.filter(e=>e.dept===fd.get('dept')).forEach(e=>{e.start=fd.get('start');e.end=fd.get('end')});save();closeModal();render();showToast('تم تحديث مواعيد القسم')});document.getElementById('cancelModal').onclick=closeModal}
    function bindViewEvents(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{activeView=b.dataset.view;render();closeSidebar()});let add=document.getElementById('addEmployee');if(add)add.onclick=addEmployeeModal;let manual=document.getElementById('manualAttendance');if(manual)manual.onclick=attendanceModal;let edit=document.getElementById('editSchedule');if(edit)edit.onclick=scheduleModal;let filter=document.getElementById('statusFilter');if(filter)filter.onclick=()=>{let states=['all','present','late','absent','leave'];attendanceFilter=states[(states.indexOf(attendanceFilter)+1)%states.length];render()};let search=document.getElementById('tableSearch');if(search)search.oninput=()=>{let q=search.value.trim().toLowerCase();let rows=document.querySelectorAll('#employeeRows tr, #payrollRows tr');rows.forEach(row=>row.style.display=row.textContent.toLowerCase().includes(q)?'':'none')};let dl=document.querySelectorAll('#downloadQr');dl.forEach(b=>b.onclick=downloadQr);let ex=document.getElementById('exportEmployees');if(ex)ex.onclick=()=>exportCsv(employees.map(e=>({الاسم:e.name,اسم_المستخدم:e.username,نوع_الحساب:e.accountType==='supervisor'?'مشرف':'موظف',الوظيفة:e.role,القسم:e.dept,الحالة:statusLabels[e.status],الحضور:e.in,الراتب:e.salary,المكافأة:e.bonus})),'الموظفون');let ep=document.getElementById('exportPayroll');if(ep)ep.onclick=()=>exportCsv(employees.map(e=>({الاسم:e.name,القسم:e.dept,الراتب:e.salary,المكافأة:e.bonus,الخصومات:e.deduction||0,الصافي:Number(e.salary)+Number(e.bonus||0)-Number(e.deduction||0)})),'الرواتب');let pr=document.getElementById('printReport');if(pr)pr.onclick=()=>window.print();let saveDefaults=document.getElementById('saveDefaults');if(saveDefaults)saveDefaults.onclick=()=>showToast('تم حفظ مواعيد العمل الافتراضية');let saveCompany=document.getElementById('saveCompany');if(saveCompany)saveCompany.onclick=()=>{localStorage.setItem('dawamCompany',document.getElementById('companyName').value);showToast('تم حفظ بيانات الشركة')};let change=document.getElementById('changePassword');if(change)change.onclick=changeCurrentPassword;document.querySelectorAll('[data-employee]').forEach(b=>b.onclick=()=>accountModal(Number(b.dataset.employee)));document.querySelectorAll('[data-request-action]').forEach(button=>button.onclick=()=>reviewRequest(button.dataset.requestId,button.dataset.requestAction))}
    function downloadQr(){let a=document.createElement('a');a.href=qrUrl();a.download='dawam-qr-'+dayKey()+'.png';a.target='_blank';a.click();showToast('جاري تجهيز رمز QR اليومي')}
    function exportCsv(rows,name){if(!rows.length)return showToast('لا توجد بيانات للتصدير');let headers=Object.keys(rows[0]),csv='\ufeff'+headers.join(',')+'\n'+rows.map(row=>headers.map(h=>'"'+String(row[h]??'').replaceAll('"','""')+'"').join(',')).join('\n');let blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();URL.revokeObjectURL(url);showToast('تم تصدير الملف بنجاح')}
